mapper.select:
select rule_id as ruleId, rule_classify as ruleClassify, rule_type as ruleType, rule_param as ruleParam, table_data_name as tableDataName, checked_field_name as checkedFieldName, checked_filed_value as checkedFiledValue , rule_method as ruleMethod, rule_content as ruleContent, rule_prompt as rulePrompt, isStart as isstart, pbc_asset_code as pbcAssetCode , rule_identify as ruleIdentify , PARAMS01, PARAMS02, PARAMS03, PARAMS04, related_table as relatedTable, update_time as updateDataTime, DATA_ID as dataId from pbc_check_rule_info
and pbc_asset_code like concat('%',#{pbcAssetCode},'%')
and rule_classify = #{ruleClassify}
and table_data_name like concat('%',#{tableDataName},'%')
#{item,jdbcType=VARCHAR}
and checked_field_name like concat('%',#{checkedFieldName},'%')
and rule_type = #{ruleType}
#{item,jdbcType=VARCHAR}
and isStart = #{isstart}
and rule_content like concat('%',concat(#{ruleContent}),'%')
and rule_prompt like concat('%',concat(#{rulePrompt}),'%')
and rule_id like concat('%',concat(#{ruleId}),'%')
and rule_identify = #{ruleIdentify}

select rule_id ,rule_classify ,rule_type ,rule_param , table_data_name ,
       checked_field_name , checked_filed_value  ,rule_method ,rule_content ,
       rule_prompt ,isStart ,pbc_asset_code  ,rule_identify ,PARAMS01,PARAMS02,PARAMS03,PARAMS04,related_table,update_time from PBC_CHECK_RULE_INFO where rule_id = #{ruleId,jdbcType=VARCHAR}
